import numpy as np # Dùng np.arange(start,end,step)
# Import PolynomialFeatures
from sklearn.linear_model import LinearRegression
from sklearn.preprocessing import PolynomialFeatures
from sklearn.model_selection import GridSearchCV

param_grid = {
    'poly_features__degree': np.arange(1,10,1)
}

# Tạo pipeline nối tiền xử lý và mô hình giống bước hồi nãy
from sklearn.pipeline import make_pipeline
model_pipeline_poly = Pipeline([
    ('preprocessor', preprocessor),
    ('poly_features', PolynomialFeatures(degree=2)),
    ('regressor', LinearRegression())
])

grid = GridSearchCV(
    estimator=model_pipeline_poly,      # Đưa pipeline vào
    param_grid=param_grid,   # Đưa lưới tham số vào
    cv=5,                    # Cross-validation: Chia làm 5 phần để kiểm tra chéo (tránh học vẹt)
    scoring='accuracy',      # Tiêu chí đánh giá: Độ chính xác
    n_jobs=-1,               # Dùng tất cả nhân CPU để chạy cho nhanh
    verbose=2                # Hiện thông báo tiến trình
)
grid.fit(X_train, y_train)

# tìm best_params_ nên là giá trị số

#Mục đích: tìm ra giá trị C phù hợp với dữ liệu
