print(f"Best cross-validation accuracy: {grid.best_score_:.4f}")

"""Kết quả cho thấy sử dụng mô hình hồi quy Linear (Polynominal có degree=1), là mô hình tốt nhất"""

# Huấn luyện
from sklearn.linear_model import LinearRegression
from sklearn.preprocessing import PolynomialFeatures

# Re-define the pipeline with LinearRegression
model_pipeline_2 = Pipeline([
    ('preprocessor', preprocessor),
    ('poly_features', PolynomialFeatures(degree=1)),
    ('regressor', LinearRegression())
])

model_pipeline_2.fit(X_train, y_train)

# Dự đoán
y_pred = model_pipeline_2.predict(X_test)

# Đánh giá các chỉ số hồi quy
from sklearn.metrics import mean_absolute_error, mean_squared_error, r2_score

