    # 1. Biểu đồ Tương quan (Scatter Plot)
    plt.subplot(1, 2, 1)
    # Vẽ các điểm dự báo
    plt.scatter(y_true, y_pred, alpha=0.6, color='blue', label='Dữ liệu')

    # Vẽ đường chéo hoàn hảo (Nếu đoán đúng 100% thì điểm sẽ nằm trên đường này)
    max_val = max(max(y_true), max(y_pred))
    min_val = min(min(y_true), min(y_pred))
    plt.plot([min_val, max_val], [min_val, max_val], color='red', linestyle='--', label='Hoàn hảo')

    plt.xlabel('Giá Thực Tế (USD)')
    plt.ylabel('Giá Dự Báo (USD)')
    plt.title('So sánh Giá Thực tế vs Dự Báo')
    plt.legend()
    plt.grid(True, alpha=0.3)

    # 2. Biểu đồ Phân phối Lỗi (Residual Distribution)
    # Để xem lỗi lệch về phía nào nhiều hơn (đoán quá cao hay quá thấp)
    plt.subplot(1, 2, 2)
    errors = y_true - y_pred
    sns.histplot(errors, kde=True, color='purple')
    plt.axvline(x=0, color='red', linestyle='--') # Đường 0 (Không lỗi)
    plt.xlabel('Độ lệch (Thực tế - Dự báo)')
    plt.title('Phân phối sai số (Residuals)')
    plt.grid(True, alpha=0.3)

    plt.tight_layout()
    plt.show()

